SELECT t1.CITY AS "Account Branch City",t1.ID AS "Account Branch Id",t0.sym AS "Symbol" FROM trading.trades AS t0 LEFT OUTER JOIN ref_data.account_master AS t2 ON (t2.ID = t0.account_id) LEFT OUTER JOIN ref_data.branch_master AS t1 ON (t1.ID = t2.BRANCH_ID) WHERE t0.sym = 'AAPL' AND t0.in_z <= '2023-12-01 12:00:00' AND (t0.out_z > '2023-12-01 12:00:00' OR t0.out_z IS NULL)
